{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C03","C20","C23","C27","C30","C51","C19","C31","C01","C16","C81","C93","C121","C122","C79","C102","C116"],
  "contradictory_card_ids": ["C53"],
  "prediction_basis_card_ids": ["C03","C20","C23","C27","C30","C19","C31","C01","C16","C81","C93","C121","C122"],
  "claims": [
    {
      "claim": "The query is a 3-methoxy-N-methyl-morphinan-6-one (hydrocodone skeleton); the closest morphinan comparator morphine has measured oral bioavailability 27.7% to 100% in cirrhosis and about 47% in healthy participants.",
      "card_ids": ["C03","C20","C23","C27","C30","C51"]
    },
    {
      "claim": "L3 exposure records show morphine achieves substantial systemic exposure after oral dosing, with AUC0-inf 383.6 to 440.6 ng·h/mL after a single oral dose and AUC0-t 359 ng·h/mL after a 100 mg extended-release capsule, consistent with meaningful oral absorption.",
      "card_ids": ["C81","C93","C121","C122"]
    },
    {
      "claim": "L3 records for naltrexone, a related but less transferable morphinan, show measurable oral Cmax of 543 to 584 pg/mL after a 2.4 mg oral solution, confirming oral absorption for the opioid scaffold.",
      "card_ids": ["C79","C102","C116"]
    },
    {
      "claim": "Other L3 exposure records concern structurally unrelated molecules such as DHE, DHEC, donepezil, estrone, equilin, tozadenant, naloxone-3-glucuronide, and griseofulvin, and do not bear on the morphinan query.",
      "card_ids": ["C80","C82","C83","C84","C105","C107","C110","C120"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C81","C93","C121","C122","C79","C102","C116"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule; the decision relies on morphinan and opioid comparators plus physicochemical priors.",
    "Most L3 records report AUC or Cmax without an IV comparator, so they do not quantify F for the comparators.",
    "High opioid F values are mostly from cirrhotic patients; pentazocine healthy control F was 0.18, though morphine healthy F about 47% and pethidine normal 0.48 support F >= 20% without cirrhosis.",
    "No formulation, dose, or prandial-state data specific to the query are supplied."
  ],
  "decision_summary": "Prediction remains high. L3 oral exposure records for the closest comparator morphine show substantial systemic exposure after oral dosing (AUC0-inf about 384 to 441 ng·h/mL), consistent with F >= 20%. Naltrexone records confirm measurable oral absorption for a related morphinan. No L3 record provides affirmative evidence for F < 20%. Confidence stays high because the evidence is consistent and the threshold is modest."
}

